"use client";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabaseClient";
import { useEffect, useState } from "react";

export default function Navbar() {
  const [user, setUser] = useState(null);
  const router = useRouter();

  useEffect(() => {
    supabase.auth.getUser().then(({ data }) => {
      setUser(data.user);
    });
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    router.push("/auth/login");
  };

  return (
    <nav className="w-full bg-white border-b shadow-sm px-6 py-3 flex justify-between items-center">
      <h1
        className="text-2xl font-bold cursor-pointer"
        onClick={() => router.push("/dashboard")}
      >
        NoteForge
      </h1>

      {user ? (
        <button
          onClick={handleLogout}
          className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600"
        >
          Logout
        </button>
      ) : (
        <button
          onClick={() => router.push("/auth/login")}
          className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600"
        >
          Login
        </button>
      )}
    </nav>
  );
}

"use client";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabaseClient";
import { useEffect, useState } from "react";
import { Moon, Sun } from "lucide-react";

export default function Navbar() {
  const [user, setUser] = useState(null);
  const [theme, setTheme] = useState("light");
  const router = useRouter();

  // Fetch logged-in user
  useEffect(() => {
    supabase.auth.getUser().then(({ data }) => setUser(data?.user || null));
  }, []);

  // -------------------------------
  // Initialize theme
  // -------------------------------
  useEffect(() => {
    if (typeof window === "undefined") return;

    const savedTheme = localStorage.getItem("theme");

    if (savedTheme === "dark" || savedTheme === "light") {
      setTheme(savedTheme);
      document.documentElement.classList.toggle("dark", savedTheme === "dark");
    } else {
      const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
      const defaultTheme = prefersDark ? "dark" : "light";
      setTheme(defaultTheme);
      document.documentElement.classList.toggle("dark", defaultTheme === "dark");
    }
  }, []);

  // Update DOM + localStorage when theme changes
  useEffect(() => {
    if (typeof window === "undefined") return;
    localStorage.setItem("theme", theme);
    document.documentElement.classList.toggle("dark", theme === "dark");
  }, [theme]);

  // Logout
  const handleLogout = async () => {
    await supabase.auth.signOut();
    router.push("/auth/login");
  };

  return (
    <nav className="w-full dark:bg-gray-900 bg-white border-b dark:border-gray-800 px-6 py-3 flex justify-between items-center shadow-sm">
      {/* Logo */}
      <h1
        className="font-extrabold text-2xl cursor-pointer dark:text-white"
        onClick={() => router.push("/dashboard")}
      >
        NoteForge
      </h1>

      {/* Right Section */}
      <div className="flex items-center gap-4">

        {/* Theme Toggle */}
        <button
          onClick={() => setTheme(theme === "light" ? "dark" : "light")}
          className="p-2 rounded-lg border dark:border-gray-700 hover:bg-gray-100 dark:hover:bg-gray-800 transition"
          aria-label="Toggle theme"
        >
          {theme === "light" ? <Moon size={18} /> : <Sun size={18} />}
        </button>

        {/* User / Auth Buttons */}
        {user ? (
          <div className="flex items-center gap-3">
            {/* Avatar Placeholder */}
            <div className="w-8 h-8 rounded-full bg-gray-200 dark:bg-gray-700" />

            <button
              onClick={handleLogout}
              className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition"
            >
              Logout
            </button>
          </div>
        ) : (
          <button
            onClick={() => router.push("/auth/login")}
            className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition"
          >
            Login
          </button>
        )}
      </div>
    </nav>
  );
}

"use client";
import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabaseClient";
import NoteCard from "./components/NoteCard";
import Editor from "./components/Editor";

export default function Dashboard() {
  const [notes, setNotes] = useState([]);
  const [selected, setSelected] = useState(null);
  const [userId, setUserId] = useState("");

  useEffect(() => {
    supabase.auth.getUser().then(({ data }) => {
      if (!data.user) window.location.href = "/auth/login";
      setUserId(data.user.id);
      fetchNotes(data.user.id);
    });
  }, []);

  const fetchNotes = async (uid: string) => {
    const { data } = await supabase
      .from("notes")
      .select("*")
      .eq("user_id", uid)
      .order("created_at", { ascending: false });

    if (data) setNotes(data);
  };

  const deleteNote = async (id: string) => {
    await supabase.from("notes").delete().eq("id", id);
    fetchNotes(userId);
  };

  return (
    <div className="grid grid-cols-3 gap-6 mt-6">
      {/* Notes List */}
      <div className="col-span-1">
        <button
          onClick={() => setSelected({ id: null, title: "", content: "" })}
          className="w-full bg-blue-600 text-white py-2 rounded-lg mb-4"
        >
          + New Note
        </button>

        <div className="space-y-4">
          {notes.map((note) => (
            <NoteCard
              key={note.id}
              note={note}
              onSelect={() => setSelected(note)}
              onDelete={deleteNote}
            />
          ))}
        </div>
      </div>

      {/* Editor */}
      <div className="col-span-2">
        {selected ? (
          <Editor
            note={selected}
            onSave={() => {
              fetchNotes(userId);
              setSelected(null);
            }}
          />
        ) : (
          <div className="text-gray-500 text-lg">Select a note...</div>
        )}
      </div>
    </div>
  );
}

"use client";
import { useState } from "react";
import { supabase } from "@/lib/supabaseClient";

export default function Editor({ note, onSave }) {
  const [title, setTitle] = useState(note.title || "");
  const [content, setContent] = useState(note.content || "");

  const save = async () => {
    const user = (await supabase.auth.getUser()).data.user;

    if (!note.id) {
      await supabase.from("notes").insert({
        user_id: user.id,
        title,
        content,
      });
    } else {
      await supabase
        .from("notes")
        .update({ title, content })
        .eq("id", note.id);
    }

    onSave();
  };

  return (
    <div className="bg-white p-6 rounded-xl shadow">
      <input
        className="w-full p-3 mb-4 border rounded-lg"
        placeholder="Note title..."
        value={title}
        onChange={(e) => setTitle(e.target.value)}
      />

      <textarea
        className="w-full p-3 h-64 border rounded-lg"
        placeholder="Write your note..."
        value={content}
        onChange={(e) => setContent(e.target.value)}
      />

      <button
        onClick={save}
        className="mt-4 px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
      >
        Save
      </button>
    </div>
  );
}

"use client";
import { useState } from "react";
import { supabase } from "@/lib/supabaseClient";
import { useRouter } from "next/navigation";

export default function Login() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const login = async () => {
    await supabase.auth.signInWithPassword({ email, password });
    router.push("/dashboard");
  };

  return (
    <div className="max-w-md mx-auto mt-16 bg-white p-8 rounded-xl shadow">
      <h2 className="text-2xl font-semibold mb-4">Login</h2>

      <input
        className="w-full p-3 mb-4 border rounded-lg"
        placeholder="Email"
        onChange={(e) => setEmail(e.target.value)}
      />

      <input
        className="w-full p-3 mb-4 border rounded-lg"
        placeholder="Password"
        type="password"
        onChange={(e) => setPassword(e.target.value)}
      />

      <button
        onClick={login}
        className="w-full py-2 bg-blue-600 text-white rounded-lg"
      >
        Login
      </button>

      <p
        className="text-sm text-blue-600 mt-4 cursor-pointer"
        onClick={() => router.push("/auth/signup")}
      >
        Create an account →
      </p>
    </div>
  );
}

"use client";
import { useState } from "react";
import { supabase } from "@/lib/supabaseClient";
import { useRouter } from "next/navigation";

export default function SignupPage() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const signUp = async (e: any) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    const { error } = await supabase.auth.signUp({
      email,
      password,
    });

    setLoading(false);

    if (error) {
      setError(error.message);
    } else {
      router.push("/dashboard");
    }
  };

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-100 dark:bg-gray-900">
      <div className="bg-white dark:bg-gray-800 p-8 rounded-xl shadow-xl w-full max-w-md">
        <h2 className="text-3xl font-bold mb-6 text-center text-gray-900 dark:text-gray-100">
          Create an Account
        </h2>

        <form onSubmit={signUp} className="space-y-4">
          <input
            type="email"
            placeholder="Email"
            className="w-full p-3 rounded-lg border dark:border-gray-700 bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-white"
            onChange={(e) => setEmail(e.target.value)}
          />

          <input
            type="password"
            placeholder="Password"
            className="w-full p-3 rounded-lg border dark:border-gray-700 bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-white"
            onChange={(e) => setPassword(e.target.value)}
          />

          <button
            type="submit"
            disabled={loading}
            className="w-full py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            {loading ? "Creating account..." : "Sign Up"}
          </button>
        </form>

        {error && (
          <p className="text-red-500 text-center mt-4">{error}</p>
        )}

        <p className="text-center mt-4 text-gray-500 dark:text-gray-300">
          Already have an account?{" "}
          <a
            href="/auth/login"
            className="text-blue-500 hover:underline"
          >
            Login
          </a>
        </p>
      </div>
    </div>
  );
}

"use client";
import { supabase } from "@/lib/supabaseClient";
import { useState } from "react";

export default function AuthPage() {
  const [email, setEmail] = useState("");

  async function signInEmail() {
    const { error } = await supabase.auth.signInWithOtp({ email });
    if (error) alert(error.message);
    else alert("Check your email for the magic link");
  }

  async function signInGoogle() {
    await supabase.auth.signInWithOAuth({ provider: "google" });
  }

  return (
    <div className="p-8 max-w-md mx-auto">
      <h1 className="text-2xl mb-4">Sign in</h1>
      <input value={email} onChange={(e)=>setEmail(e.target.value)}
        className="w-full p-2 border rounded mb-3" placeholder="you@domain.com" />
      <button onClick={signInEmail} className="w-full p-2 bg-black text-white rounded">Email magic link</button>
      <div className="text-center my-3">or</div>
      <button onClick={signInGoogle} className="w-full p-2 border rounded">Continue with Google</button>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabaseClient";
import Link from "next/link";

export default function NotesClient() {
  const [notes, setNotes] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let mounted = true;
    async function load() {
      setLoading(true);
      const { data, error } = await supabase
        .from("notes")
        .select("*")
        .order("updated_at", { ascending: false });
      if (error) {
        console.error(error);
      } else if (mounted) {
        setNotes(data || []);
      }
      setLoading(false);
    }

    load();

    // realtime subscribe to changes (optional)
    const channel = supabase.channel("public:notes")
      .on("postgres_changes", { event: "*", schema: "public", table: "notes" }, payload => {
        load();
      })
      .subscribe();

    return () => {
      mounted = false;
      channel.unsubscribe();
    };
  }, []);

  if (loading) return <div>Loading...</div>;

  return (
    <div>
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl">Your notes</h2>
        <Link href="/dashboard/notes/new" className="px-3 py-1 bg-black text-white rounded">+ New</Link>
      </div>

      <div className="grid grid-cols-3 gap-4">
        {notes.map(n => (
          <Link key={n.id} href={`/dashboard/notes/${n.id}`} className="p-4 border rounded hover:bg-gray-50">
            <h3 className="font-semibold">{n.title || "Untitled"}</h3>
            <p className="text-sm text-gray-600">{(n.content || "").slice(0, 140)}</p>
          </Link>
        ))}
      </div>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabaseClient";
import { useRouter } from "next/navigation";

export default function NoteClient({ id }: { id: string }) {
  const [note, setNote] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const router = useRouter();

  useEffect(() => {
    let mounted = true;
    async function load() {
      setLoading(true);
      const { data, error } = await supabase.from("notes").select("*").eq("id", id).single();
      if (error) console.error(error);
      else if (mounted) setNote(data);
      setLoading(false);
    }
    load();
    const channel = supabase.channel(`notes:${id}`)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'notes', filter: `id=eq.${id}` }, payload => {
        setNote(payload.new ?? payload.old);
      })
      .subscribe();
    return ()=>channel.unsubscribe();
  }, [id]);

  async function save() {
    const { error } = await supabase.from("notes").update({ title: note.title, content: note.content }).eq("id", id);
    if (error) return alert(error.message);
    alert("Saved");
  }

  async function remove() {
    const { error } = await supabase.from("notes").delete().eq("id", id);
    if (error) return alert(error.message);
    router.push("/dashboard/notes");
  }

  if (loading) return <div>Loading...</div>;
  if (!note) return <div>Not found</div>;

  return (
    <div className="p-4 max-w-3xl">
      <input className="w-full p-2 mb-2 border rounded" value={note.title} onChange={e=>setNote({ ...note, title: e.target.value})} />
      <textarea className="w-full p-2 h-60 mb-2 border rounded" value={note.content} onChange={e=>setNote({ ...note, content: e.target.value})} />
      <div className="flex gap-2">
        <button onClick={save} className="px-4 py-2 bg-black text-white rounded">Save</button>
        <button onClick={remove} className="px-4 py-2 border rounded">Delete</button>
      </div>
    </div>
  );
}

"use client";
import { useState } from "react";
import { supabase } from "@/lib/supabaseClient";
import { useRouter } from "next/navigation";

export default function NewNote() {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const router = useRouter();

  async function save() {
    const user = (await supabase.auth.getSession()).data.session?.user;
    if (!user) { alert("Sign in first"); return; }

    const { data, error } = await supabase
      .from("notes")
      .insert([{ title, content, user_id: user.id }])
      .select()
      .single();

    if (error) return alert(error.message);
    router.push(`/dashboard/notes/${data.id}`);
  }

  return (
    <div className="p-4 max-w-3xl">
      <input value={title} onChange={(e)=>setTitle(e.target.value)} className="w-full p-2 mb-2 border rounded" placeholder="Title"/>
      <textarea value={content} onChange={(e)=>setContent(e.target.value)} className="w-full p-2 h-60 mb-2 border rounded" placeholder="Write..."></textarea>
      <div className="flex gap-2">
        <button onClick={save} className="px-4 py-2 bg-black text-white rounded">Save</button>
      </div>
    </div>
  );
}

