"use client";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabase";
import { useEffect, useState } from "react";

export default function Navbar() {
  const [user, setUser] = useState(null);
  const [theme, setTheme] = useState("light");
  const router = useRouter();

  // Fetch logged-in user
  useEffect(() => {
    supabase.auth.getUser().then(({ data }) => setUser(data?.user || null));
  }, []);

  // -------------------------------
  // Initialize theme
  // -------------------------------
  useEffect(() => {
    if (typeof window === "undefined") return;

    const savedTheme = localStorage.getItem("theme");

    if (savedTheme === "dark" || savedTheme === "light") {
      setTheme(savedTheme);
      document.documentElement.classList.toggle("dark", savedTheme === "dark");
    } else {
      const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
      const defaultTheme = prefersDark ? "dark" : "light";
      setTheme(defaultTheme);
      document.documentElement.classList.toggle("dark", defaultTheme === "dark");
    }
  }, []);

  // Update DOM + localStorage when theme changes
  useEffect(() => {
    if (typeof window === "undefined") return;
    localStorage.setItem("theme", theme);
    document.documentElement.classList.toggle("dark", theme === "dark");
  }, [theme]);

  // Logout
  const handleLogout = async () => {
    await supabase.auth.signOut();
    router.push("/auth/login");
  };

  return (
    <nav className="w-full dark:bg-gray-900 bg-white border-b dark:border-gray-800 px-6 py-3 flex justify-between items-center shadow-sm">
      {/* Logo */}
      <h1
        className="font-extrabold text-2xl cursor-pointer dark:text-white"
        onClick={() => router.push("/dashboard")}
      >
        NoteForge
      </h1>

      {/* Right Section */}
      <div className="flex items-center gap-4">

        {/* Theme Toggle */}
        <button
          onClick={() => setTheme(theme === "light" ? "dark" : "light")}
          className="p-2 rounded-lg border dark:border-gray-700 hover:bg-gray-100 dark:hover:bg-gray-800 transition"
          aria-label="Toggle theme"
        >
          {theme === "light" ? "🌙" : "☀️"}
        </button>

        {/* User / Auth Buttons */}
        {user ? (
          <div className="flex items-center gap-3">
            {/* Avatar Placeholder */}
            <div className="w-8 h-8 rounded-full bg-gray-200 dark:bg-gray-700" />

            <button
              onClick={handleLogout}
              className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition"
            >
              Logout
            </button>
          </div>
        ) : (
          <button
            onClick={() => router.push("/auth/login")}
            className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition"
          >
            Login
          </button>
        )}
      </div>
    </nav>
  );
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import formidable from "formidable";
import fs from "fs";
import path from "path";
import pdf from "pdf-parse";
import mammoth from "mammoth";
import { supabaseAdmin } from "@/lib/supabaseServer";

// disable next default body parser
export const runtime = "nodejs";
export const revalidate = 0;
export const config = { api: { bodyParser: false } };

export async function POST(req: NextRequest) {
  // parse multipart
  const form = new formidable.IncomingForm({ keepExtensions: true });
  const parsed = await new Promise<{ file: formidable.File }>((resolve, reject) => {
    form.parse(req as any, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ file: files.file });
    });
  });

  const file = parsed.file;
  if (!file) return NextResponse.json({ error: "no file" }, { status: 400 });

  // Read file buffer
  const buffer = fs.readFileSync(file.filepath);

  // upload to supabase storage
  const filename = `${Date.now()}_${path.basename(file.originalFilename || file.newFilename)}`;
  const bucket = "uploads";
  const { data: uploadData, error: uploadErr } = await supabaseAdmin.storage.from(bucket).upload(filename, buffer, {
    contentType: file.mimetype || undefined,
    upsert: false,
  });

  if (uploadErr) {
    console.error("uploadErr", uploadErr);
    return NextResponse.json({ error: uploadErr.message }, { status: 500 });
  }

  const { data: publicData } = supabaseAdmin.storage.from(bucket).getPublicUrl(uploadData.path);

  let extractedText: string | null = null;
  // do lightweight extraction for pdf and docx
  const lower = (file.originalFilename || "").toLowerCase();
  try {
    if (lower.endsWith(".pdf")) {
      const parsedPdf = await pdf(buffer);
      extractedText = parsedPdf.text;
    } else if (lower.endsWith(".docx")) {
      const result = await mammoth.extractRawText({ buffer });
      extractedText = result.value;
    } else {
      // other types: return only public url (PPTX/doc non-docx not extracted here)
    }
  } catch (err) {
    console.error("extraction error", err);
  }

  return NextResponse.json({
    publicUrl: publicData.publicUrl,
    extractedText,
  });
}

