      if (!res.ok) throw new Error("Upload failed");
      const json = await res.json();

      if (json.extractedText) {
        editor?.chain().focus().setContent(`<p>${escapeHtml(json.extractedText).replace(/\n/g, "</p><p>")}</p>`).run();
