      }
    } catch (err) {
      console.error(err);
      alert("Import failed");
    } finally {
      setIsProcessingFile(false);
    }
  };

  // ---------- AI ----------
  const callAi = async (mode: "summarize" | "improve") => {
    if (!editor) return;
    const text = editor.getText();
    if (!text || text.trim().length < 10) return;

    setAiLoading(true);
    try {
      const res = await fetch("/api/ai/summarize", {
