    if (!editor) return;
    const onUpdate = ({ editor }: any) => {
      const text = editor.getText();
      if (text.length > 20) debouncedAI(text);
    };
    editor.on("update", onUpdate);
    return () => {
      editor.off("update", onUpdate);
      debouncedAI.cancel();
    };
  }, [editor, debouncedAI]);

  return (
    <div className="space-y-4">
      {/* Title + Save */}
      <div className="flex gap-3 items-center">
