  y: number;
  size: number;
  color: string;
  delay: number;
  duration: number;
}

const themeColors: Record<BackgroundTheme, string[]> = {
  cyber: [
    'hsl(217 91% 60% / 0.15)',
    'hsl(38 92% 50% / 0.12)',
    'hsl(280 70% 50% / 0.1)',
    'hsl(160 70% 40% / 0.08)',
